#include <iostream>
#include <string>
#include <cmath>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string line;
    while (std::getline(std::cin, line)) {
        if (line.empty()) continue;
        double d = std::stod(line);
        long long result = static_cast<long long>(std::floor(d / 2.0) + 1.0);
        std::cout << result << '\n';
    }
    return 0;
}

